@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@700&display=swap');

:root { --ink: #25302d; --muted: #82908b; --green: #2f7d68; --pale: #e7f1ed; --line: #e7ecea; --paper: #fff; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; color: var(--ink); background: #f4f7f5; font-family: 'DM Sans', Arial, sans-serif; display: grid; place-items: center; padding: 30px 18px; }
.app-shell { width: 100%; max-width: 650px; }
.todo-card { background: var(--paper); border: 1px solid #edf1ef; border-radius: 24px; padding: 42px 44px 28px; box-shadow: 0 18px 55px rgba(38, 70, 59, .09); }
.app-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 31px; }
.eyebrow { margin: 0 0 10px; color: var(--green); font-size: 11px; font-weight: 700; letter-spacing: 1.8px; }
h1 { font-family: 'Playfair Display', Georgia, serif; font-size: 42px; line-height: 1.1; margin: 0; letter-spacing: -.7px; }
.subtitle { color: var(--muted); margin: 10px 0 0; font-size: 14px; }
.header-mark { width: 48px; height: 48px; display: grid; place-items: center; background: var(--pale); color: var(--green); border-radius: 15px; font-size: 25px; font-weight: 700; transform: rotate(8deg); }
.add-form { display: flex; gap: 10px; margin-bottom: 35px; }
.add-form input { flex: 1; min-width: 0; border: 1px solid #dfe8e4; border-radius: 11px; padding: 14px 16px; color: var(--ink); background: #fbfcfc; font: inherit; outline: none; transition: border .2s, box-shadow .2s; }
.add-form input::placeholder { color: #a3aeaa; }
.add-form input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(47,125,104,.12); }
.add-form button { border: 0; border-radius: 11px; padding: 0 17px; color: white; background: var(--green); font: 600 14px 'DM Sans', sans-serif; cursor: pointer; transition: transform .15s, background .15s; }
.add-form button:hover { background: #256754; transform: translateY(-1px); }
.add-form button span { font-size: 18px; vertical-align: -1px; margin-left: 3px; }
.list-toolbar { display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); padding-bottom: 14px; }
.list-toolbar h2 { margin: 0; font-size: 16px; font-weight: 700; }
.count { margin: 0; color: var(--green); font-size: 12px; font-weight: 600; }
.task-list { display: flex; flex-direction: column; }
.task { display: flex; align-items: center; gap: 13px; min-height: 64px; border-bottom: 1px solid var(--line); animation: appear .2s ease-out; }
.complete-button { flex: 0 0 auto; width: 21px; height: 21px; border: 1.5px solid #b9cbc4; border-radius: 50%; background: transparent; cursor: pointer; position: relative; }
.task[data-completed="true"] .complete-button { border-color: var(--green); background: var(--green); }
.task[data-completed="true"] .complete-button::after { content: '✓'; position: absolute; color: white; font-size: 14px; line-height: 18px; left: 3px; top: 0; }
.task-text { flex: 1; font-size: 14px; line-height: 1.4; overflow-wrap: anywhere; }
.task[data-completed="true"] .task-text { color: #9aa6a2; text-decoration: line-through; }
.delete-button { border: 0; background: transparent; color: #a6b2ae; font-size: 21px; line-height: 1; padding: 7px; cursor: pointer; border-radius: 7px; }
.delete-button:hover { color: #c25c5c; background: #fff2f1; }
.empty-state { text-align: center; color: var(--muted); font-size: 14px; line-height: 1.8; padding: 33px 0 20px; margin: 0; }
.empty-state span { font-size: 12px; color: #aab5b1; }
.page-note { color: #9aa7a2; font-size: 11px; text-align: center; margin: 18px 0 0; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 520px) { .todo-card { padding: 31px 22px 22px; border-radius: 19px; } h1 { font-size: 36px; } .add-form { flex-direction: column; } .add-form button { height: 46px; } }

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.getElementById('task-input');
  const list = document.getElementById('task-list');
  const emptyState = document.getElementById('empty-state');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const countLabel = document.getElementById('count-label');
  let tasks = [];

  function render() {
    list.replaceChildren();
    tasks.forEach((task) => {
      const item = document.createElement('div');
      item.className = 'task';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const complete = document.createElement('button');
      complete.type = 'button';
      complete.className = 'complete-button';
      complete.dataset.testid = 'task-complete';
      complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      complete.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', 'Delete task');
      remove.innerHTML = '&times;';
      remove.addEventListener('click', () => {
        tasks = tasks.filter((entry) => entry.id !== task.id);
        render();
      });

      item.append(complete, text, remove);
      list.append(item);
    });
    const remaining = tasks.filter((task) => !task.completed).length;
    count.textContent = remaining;
    countLabel.textContent = remaining === 1 ? 'task left' : 'tasks left';
    emptyState.hidden = tasks.length !== 0;
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }
    tasks.push({ id: Date.now() + Math.random(), text, completed: false });
    input.value = '';
    render();
    input.focus();
  });
  render();
})();

